// === Tab: mySketch ===
// Tribute to Victor Vasarely, with his work "Keple-Gestalt" (1968)
// https://www.wikiart.org/en/victor-vasarely/keple-gestalt-1968

OPC.color("BG_COLOR", "#0D0D0D")
OPC.slider("factor", 2, 0, 4, 1)
OPC.color('color1', "#7DD510")
OPC.color("color2", '#315CA6')
OPC.color("color3", '#925EC9')
OPC.toggle('borders', true)

let cw, ch
let hexSize, hexWidth, hexHeight
let marginX, marginY
let f

function setup() {
  pixelDensity(1)
  recalculateMeasures()
  recalculatePalette()

  cw = hexWidth * (6 * f) + 2 * marginX
  ch = hexHeight * (6 * f) + 2 * marginY
  createCanvas(cw, ch)
}

let recalculateMeasures = () => {
  f = 2 ** factor
  hexSize = 85 / f
  hexWidth = hexSize * 2
  hexHeight = hexSize * sqrt(3)
  marginX = hexWidth * 2 ** (factor - 1) + hexWidth / 2
  marginY = (hexHeight * 2 ** (factor - 1)) / 2
}

function draw() {
  background(BG_COLOR)
  recalculateMeasures()

  push()
  translate(marginX, marginY)

  if (borders) {
    stroke(BG_COLOR)
    strokeWeight(2 ** (1 - factor))
  } else {
    noStroke()
  }

  let sx, sy

  sx = 2 * f
  sy = 0
  w = 2 * f
  h = 4 * f
  for (let i = sx; i < sx + w; i++) {
    for (let j = sy; j < sy + h; j++) {
      if (j < sy + h / 4 || i < sx + w / 2) {
        let v = abs(i - sx - (j - sy)) / h
        if (v < 0.5) {
          fillAndStroke(lerpColor(color(palette.c1[1]), color(palette.c1[0]), v * 2))
        } else {
          fillAndStroke(
            lerpColor(color(palette.c1[0]), color(palette.c1[2]), (v - 0.5) * 2)
          )
        }
        drawA(i, j)
        drawA(7 * f + (sx - i) - 1, 6 * f + (sy - j) - 1)
      }
    }
  }

  sx = 3 * f
  sy = f
  w = 2 * f
  h = 3 * f
  for (let i = sx; i < sx + w; i++) {
    for (let j = sy; j < sy + h; j++) {
      let ni = i
      let nj = j + (i - sx)
      if (i < sx + f || j >= sy + h - f) {
        let v = (nj - sy) / (h + 2 * f)
        let stop = 3 / 5
        if (v < stop) {
          fillAndStroke(
            lerpColor(
              color(palette.c2[0]),
              color(palette.c2[1]),
              map(abs(stop / 2 - v), 0, stop / 2, 1, 0)
            )
          )
        } else {
          fillAndStroke(
            lerpColor(
              color(palette.c2[0]),
              color(palette.c2[2]),
              map(v, stop, 1, 0, 1)
            )
          )
        }
        drawC(ni, nj)

        v = (nj - sy + 1) / (h + 2 * f)
        if (v < stop) {
          fillAndStroke(
            lerpColor(
              color(palette.c2[0]),
              color(palette.c2[2]),
              map(abs(v + 1 / 5 - (stop + 1 / 5) / 2), 0, stop - 1 / 5, 1, 0)
            )
          )
        } else {
          fillAndStroke(
            lerpColor(
              color(palette.c2[0]),
              color(palette.c2[1]),
              map(v, stop, 1, 0, 1)
            )
          )
        }
        drawC(6 * f + (sx - ni) - 1, 5 * f + (sy - nj) - 1 - 1)
      }
    }
  }

  sx = 3 * f
  sy = f
  w = f
  h = f
  for (let i = sx; i < sx + w; i++) {
    for (let j = sy; j < sy + h; j++) {
      fillAndStroke(
        lerpColor(
          color(palette.c3[0]),
          color(palette.c3[2]),
          map(i + (j - h) - sx, 0, h * 1.5, 1, 0)
        )
      )
      drawB(i + (j - h), j)
      fillAndStroke(
        lerpColor(
          color(palette.c3[0]),
          color(palette.c3[1]),
          map(i + (j - h) - sx, 0, h * 1.5, 0, 1)
        )
      )
      drawB(6 * f - 1 + (sx - i) - 1 - (j - sy), 5 * f + (sy - j) - 1)
    }
  }

  sx = 4 * f
  sy = 2 * f
  w = f
  h = 2 * f
  for (let i = sx; i < sx + w; i++) {
    for (let j = sy; j < sy + h; j++) {
      let v = 1 / w
      let nv = v * (sx - i + (j - sy))

      if (nv < 1) {
        fillAndStroke(
          lerpColor(
            color(palette.c3[0]),
            color(palette.c3[1]),
            map(nv, 1, -1, 0, 1)
          )
        )
      } else {
        fillAndStroke(
          lerpColor(
            color(palette.c3[0]),
            color(palette.c3[2]),
            map(nv, 1, 2, 0, 1)
          )
        )
      }
      drawA(i, j)
    }
  }
  pop()
}

function parameterChanged(variableName) {
  if (variableName.startsWith('color')) {
    recalculatePalette()
  }
}

let recalculatePalette = () => {
  let colors = [color1, color2, color3].map(c => color(c))
  palette = {
    c1: [
      colors[0],
      lerpColor(colors[0], color(255), 0.8),
      lerpColor(colors[0], color(0), 1),
    ],
    c2: [
      colors[1],
      lerpColor(colors[1], color(255), 0.8),
      lerpColor(colors[1], color(0), 1),
    ],
    c3: [
      colors[2],
      lerpColor(colors[2], color(255), 0.8),
      lerpColor(colors[2], color(0), 1),
    ],
  }
}

let withAlpha = (c, alpha) => {
  let newColor = color(c)
  newColor.setAlpha(alpha)
  return newColor
}

let coords = (i, j) => {
  let x = i * hexWidth - hexWidth / 2 - Math.ceil((j / 2) * hexWidth)
  let y = j * hexHeight
  return [x, y]
}

let fillAndStroke = (c) => {
  fill(c)
  if (!borders) {
    stroke(c)
  }
}

let drawA = (i, j) => {
  let [x, y] = coords(i, j)
  beginShape()
  vertex(x, y)
  vertex(x + hexWidth, y)
  vertex(x + hexWidth / 2, y + hexHeight)
  vertex(x - hexWidth / 2, y + hexHeight)
  endShape(CLOSE)
}

let drawB = (i, j) => {
  let [x, y] = coords(i, j)
  beginShape()
  vertex(x, y)
  vertex(x + hexWidth, y)
  vertex(x + (3 * hexWidth) / 2, y + hexHeight)
  vertex(x + hexWidth / 2, y + hexHeight)
  endShape(CLOSE)
}

let drawC = (i, j) => {
  let [x, y] = coords(i, j)
  beginShape()
  vertex(x, y)
  vertex(x + hexWidth / 2, y + hexHeight)
  vertex(x, y + hexHeight * 2)
  vertex(x - hexWidth / 2, y + hexHeight)
  endShape(CLOSE)
}

